class Solution {
    private int[] parent, rank;
    public int largestComponentSize(int[] nums) {
        int max = 0;
        for (int n : nums) max = Math.max(max, n);
        parent = new int[max + 1];
        rank = new int[max + 1];
        for (int i = 0; i <= max; i++) parent[i] = i;
        for (int num : nums) {
            for (int f = 2; f * f <= num; f++) {
                if (num % f == 0) {
                    union(num, f);
                    union(num, num / f);
                }
            }
        }
        java.util.Map<Integer, Integer> count = new java.util.HashMap<>();
        int result = 0;
        for (int num : nums) {
            int root = find(num);
            count.put(root, count.getOrDefault(root, 0) + 1);
            result = Math.max(result, count.get(root));
        }
        return result;
    }
    private int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    private void union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (rank[ra] < rank[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra;
        if (rank[ra] == rank[rb]) rank[ra]++;
    }
}

import java.util.*;

class Solution {
    private int[] parent;
    private int[] size;
    public int largestComponentSize(int[] nums) {
        int max = 0;
        for (int n : nums) max = Math.max(max, n);
        parent = new int[max + 1];
        size = new int[max + 1];
        for (int i = 0; i <= max; i++) { parent[i] = i; size[i] = 1; }
        Map<Integer, Integer> primeToNode = new HashMap<>();
        for (int num : nums) {
            List<Integer> primes = getPrimeFactors(num);
            for (int p : primes) {
                if (primeToNode.containsKey(p)) {
                    union(num, primeToNode.get(p));
                } else {
                    primeToNode.put(p, num);
                }
            }
        }
        Map<Integer, Integer> componentCount = new HashMap<>();
        int result = 0;
        for (int num : nums) {
            int root = find(num);
            int cnt = componentCount.getOrDefault(root, 0) + 1;
            componentCount.put(root, cnt);
            result = Math.max(result, cnt);
        }
        return result;
    }
    private List<Integer> getPrimeFactors(int n) {
        List<Integer> factors = new ArrayList<>();
        for (int f = 2; f * f <= n; f++) {
            if (n % f == 0) {
                factors.add(f);
                while (n % f == 0) n /= f;
            }
        }
        if (n > 1) factors.add(n);
        return factors;
    }
    private int find(int x) {
        while (parent[x] != x) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }
    private void union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (size[ra] < size[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra;
        size[ra] += size[rb];
    }
}
